/** Flatten a row-major matrix into a contiguous row-major buffer. */
export function flatten(m) {
    const rows = m.length;
    const cols = rows > 0 ? m[0].length : 0;
    const out = new Array(rows * cols);
    for (let i = 0; i < rows; i++) {
        const row = m[i];
        for (let j = 0; j < cols; j++) {
            out[i * cols + j] = row[j];
        }
    }
    return out;
}
/** Reshape a contiguous row-major buffer into a `rows` x `cols` matrix. */
export function reshape(flat, rows, cols) {
    const out = new Array(rows);
    for (let i = 0; i < rows; i++) {
        const row = new Array(cols);
        for (let j = 0; j < cols; j++) {
            row[j] = flat[i * cols + j];
        }
        out[i] = row;
    }
    return out;
}
/** Copy a contiguous buffer. */
export function copyFlat(a) {
    const out = new Array(a.length);
    for (let i = 0; i < a.length; i++) {
        out[i] = unchecked(a[i]);
    }
    return out;
}
/** Allocate a zero-filled buffer. */
export function zeros(n) {
    const out = new Array(n);
    for (let i = 0; i < n; i++) {
        out[i] = 0.0;
    }
    return out;
}
